*{box-sizing:border-box}body{margin:0;background:var(--bg);font-family:Inter,Manrope,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--ink)}.wrap{max-width:1080px;margin:auto;padding:86px 16px 36px}.eyebrow{font-size:11px;font-weight:900;letter-spacing:.12em;text-transform:uppercase;color:#567089}.head h1{font-size:30px;line-height:1.1;margin:6px 0 7px;letter-spacing:-.025em}.sub{color:var(--muted);font-size:15px;margin-bottom:22px}.hero{display:grid;grid-template-columns:1.3fr .7fr;gap:10px;margin-bottom:10px}.hero-card,.card,.panel{background:var(--paper);border:1px solid var(--line);border-radius:17px;box-shadow:0 8px 28px rgba(15,23,42,.04)}.hero-card{padding:18px}.hero-card.dark{background:linear-gradient(145deg,#172033,#20344e);color:#fff;border-color:transparent}.hero-card.dark .label,.hero-card.dark .meta{color:#c9d5e3}.label{font-size:10px;color:var(--muted);text-transform:uppercase;font-weight:900;letter-spacing:.07em;margin-bottom:7px}.big{font-size:30px;font-weight:900;letter-spacing:-.04em}.meta{font-size:12px;color:var(--muted);margin-top:5px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.card{padding:15px}.value{font-size:24px;font-weight:900;letter-spacing:-.035em}.attention{border-color:#fed7aa;background:linear-gradient(135deg,#fff,#fffaf5)}.attention .value{color:var(--warn)}.section{margin-top:14px}.section-head{display:flex;justify-content:space-between;align-items:end;gap:10px;margin-bottom:9px}.section-head h2{font-size:18px;margin:0;letter-spacing:-.02em}.section-head span{font-size:11px;color:var(--muted)}.quick{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.quick a{text-decoration:none;background:var(--paper);border:1px solid var(--line);color:var(--ink);border-radius:13px;padding:13px;font-weight:850;font-size:13px;box-shadow:0 5px 18px rgba(15,23,42,.035)}.quick a.primary{background:var(--ink);color:#fff;border-color:transparent}.panel{padding:16px}.schedule{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.slot{padding:12px;border:1px solid var(--line);border-radius:12px;background:#fbfcfe}.slot strong{display:block;font-size:14px}.slot span{display:block;color:var(--muted);font-size:11px;margin-top:3px}.empty{background:var(--paper);border:1px dashed #cbd5e1;border-radius:14px;text-align:center;color:var(--muted);padding:20px}.error{color:#9f1239;background:#fff1f2;border-color:#fecdd3}
