const c=document.getElementById('contenido');const money=n=>Number(n||0).toLocaleString('es-MX',{style:'currency',currency:'MXN',maximumFractionDigits:0});async function cargar(){try{const r=await fetch('/api/dashboard.php',{cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'No se pudo cargar el dashboard');c.innerHTML=`<div class="hero"><div class="hero-card dark"><div class="label">Ingresos del mes</div><div class="big">${money(d.caja.total)}</div><div class="meta">${d.caja.cantidad} pago${d.caja.cantidad==1?'':'s'} registrado${d.caja.cantidad==1?'':'s'}</div></div><div class="hero-card ${Number(d.pendientes)>0?'attention':''}"><div class="label">Requieren atención</div><div class="big">${d.pendientes}</div><div class="meta">alumnos pendientes</div></div></div><div class="metrics"><div class="card"><div class="label">Alumnos activos</div><div class="value">${d.alumnos_activos}</div></div><div class="card"><div class="label">Mensualidades pagadas</div><div class="value">${d.mensualidades.cantidad}</div><div class="meta">${money(d.mensualidades.total)}</div></div><div class="card"><div class="label">Intensivos activos</div><div class="value">${d.intensivos}</div></div><div class="card"><div class="label">Reposiciones</div><div class="value">${d.reposiciones}</div><div class="meta">disponibles</div></div><div class="card"><div class="label">Avisos hoy</div><div class="value">${d.avisos_hoy}</div></div><div class="card"><div class="label">Fecha operativa</div><div class="value" style="font-size:18px">${d.fecha}</div></div></div><section class="section"><div class="section-head"><h2>Acciones rápidas</h2><span>Lo más usado</span></div><div class="quick"><a href="/sesiones.php" class="primary">Tomar asistencia</a><a href="/pagos.php">Registrar pago</a><a href="/alumnos.php">Ver alumnos</a><a href="/ausencias.php">Ausencias</a></div></section><section class="section"><div class="section-head"><h2>Ocupación por horario</h2><span>${d.horarios.length} horarios con alumnos</span></div><div class="panel"><div class="schedule">${d.horarios.length?d.horarios.map(x=>`<div class="slot"><strong>${String(x.hora_inicio).slice(0,5)}–${String(x.hora_fin).slice(0,5)}</strong><span>${x.alumnos} alumno${x.alumnos==1?'':'s'}</span></div>`).join(''):'<div class="empty">Sin alumnos asignados.</div>'}</div></div></section>`}catch(e){c.innerHTML=`<div class="empty error">${String(e.message||'No se pudo cargar el dashboard')}</div>`}}cargar();
</script></body></html>